                previous_b = b
                b = _lasso_divide(
                    _lasso_float_sum(
                        y[i]
                        - _lasso_linear_sum(w, X[i], width)
                        for i in range(n)
                    ),
                    n,
                )
                max_change = abs(b - previous_b)

